-- Moves agents still on an earlier default Marvis artwork to the current one.
-- The default avatar is stored on the row as a data URI when the agent is
-- created (handler/mika_avatar.go), so replacing the embedded SVG only
-- reaches new agents. Only exact matches of a previous default change;
-- avatars a member uploaded or picked are left alone.
UPDATE agent
SET avatar_url = 'data:image/svg+xml;base64,'
WHERE avatar_url IN (
    'data:image/svg+xml;base64,',
    'data:image/svg+xml;base64,'
);
